// REST API router. handleApi returns true when the request was an /api route.
import {
  listProjects,
  ensureProject,
  getProject,
  createIssue,
  getIssue,
  listIssues,
  updateIssue,
  addComment,
  recordNotification,
  resolveIssue,
  sweepDone,
  listClosed,
  deleteIssue,
  iceboxIssue,
  reviveIssue,
  listIcebox,
  listTags,
  renameTag,
  deleteTag,
  linkIssues,
  unlinkIssues,
  resolveLinks,
  saveIssueScreenshot,
  readIssueScreenshot,
} from './store.mjs';

// Who the mail went to, by the same rule the board uses to name a reporter: the
// widget's capture carries context.reportedBy, older or relayed issues carry a
// user:<email> tag. Recorded with the send so the receipt names the address as it
// stood that day, not whatever the tags say later.
// A relayed string is not an address: blank ones name nobody, and the board keeps
// '__none__' for the issues nobody is attached to, so neither is recorded as a
// recipient. The board's reporterEmail() reads them the same way.
function cleanEmail(value) {
  const email = String(value || '').trim().toLowerCase();
  return email && email !== '__none__' ? email : null;
}
function reporterEmail(issue) {
  const fromContext = cleanEmail(issue?.context?.reportedBy?.email);
  if (fromContext) return fromContext;
  const tag = (issue?.tags || []).find((t) => t.startsWith('user:') && t.includes('@'));
  return tag ? cleanEmail(tag.slice('user:'.length)) : null;
}

// A host app that sends through a provider usually answers with the provider's id.
// The name it gives that field is its own business, so read the handful anybody
// uses and keep nothing when none of them is there.
function notifyReceipt(out) {
  if (!out || typeof out !== 'object') return null;
  for (const key of ['receipt', 'id', 'messageId', 'message_id', 'emailId', 'email_id']) {
    const v = out[key];
    if (typeof v === 'string' && v.trim()) return v.trim();
  }
  return null;
}

export function setCors(res) {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PATCH, DELETE, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
}

// The capture widget runs on the host app's origin and needs exactly two routes
// readable cross-origin: the tag list it renders and the issue it files. Every
// other /api route returns board content, which is reporter emails, diagnostics
// and screenshot bytes. A blanket Access-Control-Allow-Origin let any page the
// operator merely visited read all of it, so the header is granted per route.
function isWidgetRoute(method, pathname) {
  if (method === 'POST' && pathname === '/api/issues') return true;
  return method === 'GET' && /^\/api\/projects\/[^/]+\/tags$/.test(pathname);
}

// CSRF guard for destructive, board-only mutations. The capture widget POSTs
// cross-origin (that must stay allowed), but DELETE/PATCH are only ever issued
// by the same-origin board UI or by header-less callers (curl, MCP). A browser
// always attaches a truthful Origin on cross-origin unsafe requests, so any
// request whose Origin doesn't match this server is a drive-by and is refused.
// Header-less callers (no Origin) pass; they aren't the CSRF threat.

