    .filter((w) => w.members.some((m) => m.userId === c.user.id))
    .map((w) => ({ id: w.id, name: w.name, key: w.key, role: w.members.find((m) => m.userId === c.user.id).role }))));

  def('GET', '/api/workspaces/:id', (c) => {
