    return ok(issueDetail(issue));
  });

  def('PATCH', '/api/issues/:key', (c) => {
    const { issue, project } = issueAccess(c.params.key, c.user, WRITE);
    const { issue: updated } = updateIssue(issue, project, c.body(), c.user);
