SP=/tmp/claude-0/-home-user-just-use-stackoverflow/0aee327b-dad0-5786-a62e-e964dcee381e/scratchpad/work/pm-s4__reuse_first__haiku__t1__20261124T081833; WS=$SP/ws; mkdir -p $SP/uitest && cat > $SP/uitest/drive.mjs <<'EOF'
// Drives headless Chrome over CDP: seeds data via API, then checks each SPA view renders without errors.
import { spawn } from 'node:child_process';
const WS = process.argv[2];
const PORT = 8771, CDP = 9339;
const srv = spawn('node', ['src/main.js'], { cwd: WS, env: { ...process.env, PORT: String(PORT), DATA_FILE: `${process.env.TMPDIR || '/tmp'}/pm-ui-${Date.now()}.json` }, stdio: 'ignore' });
const base = `http://127.0.0.1:${PORT}`;
await new Promise((r) => setTimeout(r, 800));
const api = async (m, p, b, t) => {
  const r = await fetch(base + p, { method: m, headers: { 'content-type': 'application/json', ...(t ? { authorization: `Bearer ${t}` } : {}) }, body: b && JSON.stringify(b) });
  const txt = await r.text(); return { status: r.status, body: txt ? JSON.parse(txt) : null };
};
await api('POST', '/api/auth/register', { username: 'uiuser', password: 'password123' });
const { token } = (await api('POST', '/api/auth/login', { username: 'uiuser', password: 'password123' })).body;
const ws = (await api('POST', '/api/workspaces', { name: 'UI Co', key: 'UIC' }, token)).body;
const pr = (await api('POST', `/api/workspaces/${ws.id}/projects`, { name: 'Board', key: 'BRD' }, token)).body;
const sp = (await api('POST', `/api/projects/${pr.id}/sprints`, { name: 'Sprint 1', startDate: '2026-01-01', endDate: '2026-12-31' }, token)).body;
await api('POST', `/api/sprints/${sp.id}/start`, {}, token);
await api('POST', `/api/projects/${pr.id}/issues`, { type: 'bug', title: 'Crash on save', priority: 'high', storyPoints: 3, sprintId: sp.id }, token);
await api('POST', `/api/projects/${pr.id}/issues`, { type: 'task', title: 'Backlog item', storyPoints: 2 }, token);
await api('POST', `/api/projects/${pr.id}/webhooks`, { url: 'http://127.0.0.1:1/none', events: ['issue.created'], secret: 's' }, token);

const version = await (await fetch(`http://127.0.0.1:${CDP}/json/version`).catch(() => null))?.json?.().catch(() => null);
const chrome = spawn('google-chrome', ['--headless', '--no-sandbox', '--disable-gpu', `--remote-debugging-port=${CDP}`, `--user-data-dir=${process.env.TMPDIR || '/tmp'}/pm-chrome-${Date.now()}`, 'about:blank'], { stdio: 'ignore' });
let targets;
for (let i = 0; i < 50; i++) { try { targets = await (await fetch(`http://127.0.0.1:${CDP}/json/list`)).json(); break; } catch { await new Promise((r) => setTimeout(r, 200)); } }
const page = targets.find((t) => t.type === 'page');
const ws2 = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => ws2.addEventListener('open', r));
let id = 0; const pending = new Map(); const errors = [];
ws2.addEventListener('message', (ev) => {
  const m = JSON.parse(ev.data);
  if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); }
  if (m.method === 'Runtime.exceptionThrown') errors.push(m.params.exceptionDetails.exception?.description || m.params.exceptionDetails.text);
  if (m.method === 'Runtime.consoleAPICalled' && m.params.type === 'error') errors.push(m.params.args.map((a) => a.value || a.description).join(' '));
});
const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws2.send(JSON.stringify({ id: i, method, params })); });
const evalJs = async (expr) => (await send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true })).result?.result?.value;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
await send('Runtime.enable'); await send('Page.enable');
await send('Page.navigate', { url: `${base}/` }); await sleep(800);
await evalJs(`localStorage.setItem('pm-token', ${JSON.stringify(token)}); true`);
const views = ['#/board', '#/backlog', '#/sprints', `#/sprints/${sp.id}`, '#/settings', '#/workspace', '#/search/type:bug', '#/issue/BRD-1'];
const report = {};
for (const v of views) {
  await send('Page.navigate', { url: `${base}/${v}` }); await sleep(900);
  report[v] = await evalJs(`(document.querySelector('main')||{}).innerText?.slice(0,160).replace(/\\s+/g,' ')`);
}
// drag BRD-2 card to In Progress column via DOM events
await send('Page.navigate', { url: `${base}/#/board` }); await sleep(900);
const dragOk = await evalJs(`(async () => {
  const card = document.querySelector('[data-drag="BRD-2"]'); const col = document.querySelector('[data-drop="In Progress"]');
  const dt = new DataTransfer();
  card.dispatchEvent(new DragEvent('dragstart', { bubbles: true, dataTransfer: dt }));
  col.dispatchEvent(new DragEvent('dragover', { bubbles: true, cancelable: true, dataTransfer: dt }));
  col.dispatchEvent(new DragEvent('drop', { bubbles: true, cancelable: true, dataTransfer: dt }));
  await new Promise(r => setTimeout(r, 800));
  return document.querySelector('[data-drop="In Progress"]').innerText.includes('BRD-2');
})()`);
const invalidDrag = await api('GET', '/api/issues/BRD-2', undefined, token);
console.log(JSON.stringify({ report, dragOk, issueStatusAfterDrag: invalidDrag.body.status, errors: errors.slice(0, 10) }, null, 2));
ws2.close(); chrome.kill(); srv.kill();
EOF
cd $WS && timeout 120 node $SP/uitest/drive.mjs $WS 2>&1 | head -120

